using System.Collections;
using Project.Quests;
using UnityEngine;

namespace Project.PPT
{
    public sealed class PptNpcGestureController : MonoBehaviour
    {
        private const float RotateDurationSeconds = 0.4f;
        private const float PointHoldSeconds = 2.5f;
        private const float ShrugHoldSeconds = 2f;

        [Header("Animator")]
        [SerializeField] private Animator animator;
        [SerializeField] private Transform visualRoot;

        [Header("Upper Body Pointing")]
        [Tooltip("Animator state on the masked upper-body layer for seated NPCs (e.g. Gongo in a chair).")]
        [SerializeField] private string upperBodyPointStateName = "Point";
        [Tooltip("Animator layer name that uses an upper-body AvatarMask.")]
        [SerializeField] private string upperBodyLayerName = "Upper Body";
        [Tooltip("When enabled, overrides PptNpcProfile point gesture mode on this instance.")]
        [SerializeField] private bool usePointGestureModeOverride;
        [SerializeField] private PptPointGestureMode pointGestureModeOverride = PptPointGestureMode.UpperBodyOnly;

        private PptPointGestureMode pointGestureMode = PptPointGestureMode.FullBody;
        private string pointStateName = "Point";
        private string shrugStateName = "Shrug";
        private string idleStateName = "Idle";
        private bool rotateVisualTowardBearing = true;
        private float crossFadeSeconds = 0.15f;
        private int cachedUpperBodyLayerIndex = -1;
        private Coroutine restoreRoutine;
        private AnimatorUpdateMode cachedUpdateMode;
        private bool updateModeOverridden;

        public void Configure(PptNpcProfile profile, QuestGiverNpc questGiver = null)
        {
            if (profile != null)
            {
                pointGestureMode = profile.PointGestureMode;
                pointStateName = profile.PointStateName;
                shrugStateName = profile.ShrugStateName;
                idleStateName = profile.IdleStateName;
                rotateVisualTowardBearing = profile.RotateVisualTowardBearing;
                crossFadeSeconds = profile.GestureCrossFadeSeconds;

                if (!string.IsNullOrWhiteSpace(profile.UpperBodyPointStateName))
                    upperBodyPointStateName = profile.UpperBodyPointStateName;

                if (!string.IsNullOrWhiteSpace(profile.UpperBodyLayerName))
                    upperBodyLayerName = profile.UpperBodyLayerName;
            }

            if (questGiver != null && !string.IsNullOrWhiteSpace(questGiver.IdleAnimationStateName))
                idleStateName = questGiver.IdleAnimationStateName;

            if (usePointGestureModeOverride)
                pointGestureMode = pointGestureModeOverride;

            cachedUpperBodyLayerIndex = -1;
        }

        /// <summary>
        /// Turn toward bearing (when enabled) and begin the point gesture.
        /// Yields once the point has started so callers can close UI, then restores idle in the background.
        /// </summary>
        public IEnumerator PlayPointUntilStarted(float bearingDegrees)
        {
            if (restoreRoutine != null)
            {
                StopCoroutine(restoreRoutine);
                restoreRoutine = null;
            }

            EnsureAnimator();
            if (animator == null)
                yield break;

            int gestureLayer = ResolvePointLayerIndex(out string stateName);
            if (gestureLayer < 0 || string.IsNullOrWhiteSpace(stateName))
                yield break;

            BeginUnscaledAnimator();

            if (ShouldRotateVisual())
                yield return RotateVisualToward(bearingDegrees);

            PlayGesture(stateName, gestureLayer);
            yield return new WaitForSecondsRealtime(Mathf.Max(0.05f, crossFadeSeconds + 0.1f));

            ScheduleRestore(PointHoldSeconds, gestureLayer);
        }

        public void PlayPoint(float bearingDegrees)
        {
            StartCoroutine(PlayPointUntilStarted(bearingDegrees));
        }

        public void PlayShrug()
        {
            int gestureLayer = ResolveShrugLayerIndex(out string stateName);
            if (gestureLayer < 0 || string.IsNullOrWhiteSpace(stateName))
                return;

            BeginUnscaledAnimator();
            PlayGesture(stateName, gestureLayer);
            ScheduleRestore(ShrugHoldSeconds, gestureLayer);
        }

        private bool ShouldRotateVisual()
        {
            // Upper-body-only still turns the visual root toward the bearing (seated torso aim).
            return rotateVisualTowardBearing;
        }

        private IEnumerator RotateVisualToward(float bearingDegrees)
        {
            Transform root = visualRoot != null ? visualRoot : transform;
            Quaternion target = Quaternion.Euler(0f, bearingDegrees, 0f);
            float rotateTimer = 0f;
            Quaternion start = root.rotation;
            while (rotateTimer < RotateDurationSeconds)
            {
                rotateTimer += Time.unscaledDeltaTime;
                root.rotation = Quaternion.Slerp(start, target, Mathf.Clamp01(rotateTimer / RotateDurationSeconds));
                yield return null;
            }

            root.rotation = target;
        }

        private int ResolvePointLayerIndex(out string stateName)
        {
            if (pointGestureMode == PptPointGestureMode.UpperBodyOnly)
            {
                stateName = upperBodyPointStateName;
                return ResolveUpperBodyLayerIndex(stateName);
            }

            stateName = pointStateName;
            return HasStateOnLayer(0, stateName) ? 0 : -1;
        }

        private int ResolveShrugLayerIndex(out string stateName)
        {
            stateName = shrugStateName;
            if (pointGestureMode == PptPointGestureMode.UpperBodyOnly)
                return ResolveUpperBodyLayerIndex(stateName);

            return HasStateOnLayer(0, stateName) ? 0 : -1;
        }

        private int ResolveUpperBodyLayerIndex(string stateName)
        {
            EnsureAnimator();
            if (animator == null)
                return -1;

            int layerIndex = GetUpperBodyLayerIndex();
            if (layerIndex < 0)
                return -1;

            return HasStateOnLayer(layerIndex, stateName) ? layerIndex : -1;
        }

        private int GetUpperBodyLayerIndex()
        {
            if (cachedUpperBodyLayerIndex >= 0)
                return cachedUpperBodyLayerIndex;

            EnsureAnimator();
            if (animator == null || string.IsNullOrWhiteSpace(upperBodyLayerName))
                return -1;

            for (int i = 0; i < animator.layerCount; i++)
            {
                if (animator.GetLayerName(i) != upperBodyLayerName)
                    continue;

                cachedUpperBodyLayerIndex = i;
                return i;
            }

            return -1;
        }

        private bool HasStateOnLayer(int layerIndex, string stateName)
        {
            EnsureAnimator();
            if (animator == null || string.IsNullOrWhiteSpace(stateName))
                return false;

            return animator.HasState(layerIndex, Animator.StringToHash(stateName));
        }

        private void PlayGesture(string stateName, int layerIndex)
        {
            EnsureAnimator();
            if (animator == null || string.IsNullOrWhiteSpace(stateName) || layerIndex < 0)
                return;

            if (!HasStateOnLayer(layerIndex, stateName))
                return;

            if (layerIndex > 0)
                animator.SetLayerWeight(layerIndex, 1f);

            animator.CrossFadeInFixedTime(stateName, crossFadeSeconds, layerIndex, 0f);
        }

        private void ScheduleRestore(float delay, int gestureLayer)
        {
            if (restoreRoutine != null)
                StopCoroutine(restoreRoutine);

            restoreRoutine = StartCoroutine(RestoreIdleAfter(delay, gestureLayer));
        }

        private IEnumerator RestoreIdleAfter(float delay, int gestureLayer)
        {
            yield return new WaitForSecondsRealtime(delay);
            RestoreIdle(gestureLayer);
            EndUnscaledAnimator();
            restoreRoutine = null;
        }

        private void RestoreIdle(int gestureLayer)
        {
            EnsureAnimator();
            if (animator == null)
                return;

            if (!string.IsNullOrWhiteSpace(idleStateName) && HasStateOnLayer(0, idleStateName))
                animator.CrossFadeInFixedTime(idleStateName, crossFadeSeconds, 0, 0f);

            if (gestureLayer > 0)
                animator.SetLayerWeight(gestureLayer, 0f);
        }

        private void BeginUnscaledAnimator()
        {
            EnsureAnimator();
            if (animator == null || updateModeOverridden)
                return;

            cachedUpdateMode = animator.updateMode;
            animator.updateMode = AnimatorUpdateMode.UnscaledTime;
            updateModeOverridden = true;
        }

        private void EndUnscaledAnimator()
        {
            if (!updateModeOverridden || animator == null)
                return;

            animator.updateMode = cachedUpdateMode;
            updateModeOverridden = false;
        }

        private void EnsureAnimator()
        {
            if (animator != null)
                return;

            if (visualRoot != null)
                animator = visualRoot.GetComponentInChildren<Animator>();

            if (animator == null)
                animator = GetComponentInChildren<Animator>();
        }

        private void OnDisable()
        {
            EndUnscaledAnimator();
        }
    }
}

using System;
using System.Collections;
using Project.Core;
using Project.Interaction;
using Project.Quests;
using Project.UI;
using UnityEngine;

namespace Project.PPT
{
    /// <summary>
    /// Hold-E directions interaction for NPCs with a PptNpcProfile.
    /// Tap-E talk remains on QuestGiverNpc / IVendor.
    /// </summary>
    [RequireComponent(typeof(Collider))]
    public sealed class PptNpcInteractor : MonoBehaviour, IHoldWorldUsable
    {
        private const float PostPointFeedbackDelaySeconds = 1.5f;

        [SerializeField] private string npcId = "pioneer_guide";
        [SerializeField] private PptNpcProfile profile;
        [SerializeField] private float interactRange = 3.5f;
        [SerializeField] private float holdDurationSeconds = 0.75f;
        [SerializeField] private string holdPromptText = "Hold E — Ask for directions";

        private Collider interactCollider;
        private PptNpcGestureController gestureController;
        private QuestGiverNpc questGiver;
        private bool holdActive;
        private float holdProgress;
        private Coroutine directionChoiceRoutine;

        public string NpcId => npcId;
        public PptNpcProfile Profile => profile;
        public string SpeakerDisplayName
        {
            get
            {
                if (questGiver != null && !string.IsNullOrWhiteSpace(questGiver.DisplayName))
                    return questGiver.DisplayName;
                if (profile != null && !string.IsNullOrWhiteSpace(profile.DisplayName))
                    return profile.DisplayName;
                return npcId;
            }
        }
        public float HoldDurationSeconds => holdDurationSeconds;
        public string HoldPromptText => holdPromptText;
        public bool IsHoldActive => holdActive;
        public bool OffersDirections => CanOfferDirections();

        private void Awake()
        {
            interactCollider = GetComponent<Collider>();
            gestureController = GetComponent<PptNpcGestureController>();
            questGiver = GetComponent<QuestGiverNpc>();

            if (gestureController == null)
                gestureController = gameObject.AddComponent<PptNpcGestureController>();

            if (profile != null)
                gestureController.Configure(profile, questGiver);
        }

        public float GetUsePriority(WorldUseContext context)
        {
            if (!CanOfferDirections() || !IsWithinRange(context.PlayerPosition))
                return -1f;

            if (questGiver != null
                && !WorldUseController.IsAimedAtQuestGiver(context, questGiver, interactCollider))
                return -1f;

            float distance = PlayerInteractionUtility.DistanceToInteractable(
                context.PlayerPosition,
                interactCollider,
                transform.position);

            return 900f - distance;
        }

        public bool TryUse(WorldUseContext context)
        {
            return false;
        }

        public bool CanBeginHold(WorldUseContext context)
        {
            return CanOfferDirections()
                && IsWithinRange(context.PlayerPosition)
                && (questGiver == null || WorldUseController.IsAimedAtQuestGiver(context, questGiver, interactCollider));
        }

        public void BeginHold(WorldUseContext context)
        {
            holdActive = true;
            holdProgress = 0f;
        }

        public bool TickHold(WorldUseContext context, float deltaTime, out float progress01)
        {
            if (!holdActive)
            {
                progress01 = 0f;
                return false;
            }

            if (!CanBeginHold(context))
            {
                CancelHold(context);
                progress01 = 0f;
                return false;
            }

            holdProgress += deltaTime / Mathf.Max(0.05f, holdDurationSeconds);
            progress01 = Mathf.Clamp01(holdProgress);

            if (holdProgress < 1f)
                return false;

            holdActive = false;
            OpenDirectionsMenu();
            return true;
        }

        public void CancelHold(WorldUseContext context)
        {
            holdActive = false;
            holdProgress = 0f;
        }

        /// <summary>
        /// Resolves the place, plays turn+point while the menu stays open, then invokes
        /// <paramref name="closeMenu"/>, waits 1.5s, and shows the spoken feedback.
        /// </summary>
        public IEnumerator RespondToDirectionChoice(PptEntry entry, Action closeMenu)
        {
            PptManager manager = PptManager.Instance;
            if (manager == null || entry == null)
            {
                closeMenu?.Invoke();
                yield break;
            }

            PptDirectionResult result = manager.ResolveDirection(npcId, entry, transform.position);

            if (result.Kind == PptDirectionKind.Unknown)
            {
                gestureController?.PlayShrug();
                closeMenu?.Invoke();
                yield return new WaitForSecondsRealtime(PostPointFeedbackDelaySeconds);
                ShowSpokenFeedback(result);
                yield break;
            }

            if (gestureController != null)
                yield return gestureController.PlayPointUntilStarted(result.BearingDegrees);

            if (result.Kind == PptDirectionKind.Precise && result.SpawnTracer)
                PptTerrainDirectionTracer.Spawn(transform.position + Vector3.up * 1.2f, result.AimPosition);

            closeMenu?.Invoke();
            yield return new WaitForSecondsRealtime(PostPointFeedbackDelaySeconds);
            ShowSpokenFeedback(result);
        }

        public void HandleDirectionChoice(PptEntry entry)
        {
            if (directionChoiceRoutine != null)
                StopCoroutine(directionChoiceRoutine);

            directionChoiceRoutine = StartCoroutine(RespondToDirectionChoice(entry, null));
        }

        private void ShowSpokenFeedback(PptDirectionResult result)
        {
            QuestGiverDialogUI.Show(SpeakerDisplayName, result.Phrase, null, npcAnchor: transform);
        }

        public void OpenDirectionsMenu()
        {
            Canvas canvas = FindAnyObjectByType<Canvas>();
            if (canvas == null)
                return;

            PptDirectionsMenuUI ui = PptDirectionsMenuUI.EnsureExists(canvas.transform);
            ui.Show(this);
        }

        private bool CanOfferDirections()
        {
            if (!GameSession.HasStarted)
                return false;

            if (profile == null)
            {
                PptManager manager = PptManager.Instance;
                if (manager != null && manager.TryGetNpcProfile(npcId, out PptNpcProfile loaded))
                    profile = loaded;
            }

            return profile != null && profile.HasTalkOption(PptTalkOptions.Directions);
        }

        private bool IsWithinRange(Vector3 playerPosition)
        {
            if (questGiver != null)
                return questGiver.IsWithinInteractRange(playerPosition);

            float distance = PlayerInteractionUtility.DistanceToInteractable(
                playerPosition,
                interactCollider,
                transform.position);
            return distance <= interactRange;
        }
    }
}

